// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/healthz", wrapper.GetHealth)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/languages", wrapper.ListLanguages)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/entries/search", wrapper.SearchEntries)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/entries/{id}", wrapper.GetEntry)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/concepts/{id}", wrapper.GetConcept)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/lookup", wrapper.Lookup)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/me", wrapper.GetMe)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/v1/me/credit", wrapper.SetCredit)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/contributions", wrapper.CreateContribution)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/review/next", wrapper.GetNextReview)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/credits", wrapper.ListCredits)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/v1/reviews", wrapper.DeleteReviews)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/reviews", wrapper.CreateReviews)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/approvals", wrapper.ListApprovals)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/v1/approvals", wrapper.ApproveReviewer)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/v1/approvals/{user_id}/{language}", wrapper.RevokeApproval)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/provider-quality", wrapper.GetProviderQuality)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/reviewers", wrapper.ListReviewers)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/reviewers/{user_id}/retraining", wrapper.MarkRetrained)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/disputes", wrapper.ListDisputes)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/disputes/{sense_id}/resolution", wrapper.ResolveDispute)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/sources", wrapper.ListSources)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/sources", wrapper.CreateSource)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/v1/sources/{id}", wrapper.DeleteSource)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/sources/{id}", wrapper.GetSource)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/v1/sources/{id}", wrapper.UpdateSource)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/sources/{id}/permission", wrapper.DownloadPermission)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/v1/sources/{id}/permission", wrapper.UploadPermission)
	})

	return r
}

