// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetHealth Liveness and database readiness
	// (GET /healthz)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// ListApprovals Every reviewer approval (admin)
	// (GET /v1/approvals)
	ListApprovals(ctx context.Context, request ListApprovalsRequestObject) (ListApprovalsResponseObject, error)
	// ApproveReviewer Approve a user to review a language, or change their level (admin)
	// (PUT /v1/approvals)
	ApproveReviewer(ctx context.Context, request ApproveReviewerRequestObject) (ApproveReviewerResponseObject, error)
	// RevokeApproval Remove a reviewer approval (admin)
	// (DELETE /v1/approvals/{user_id}/{language})
	RevokeApproval(ctx context.Context, request RevokeApprovalRequestObject) (RevokeApprovalResponseObject, error)
	// GetConcept A meaning across all languages
	// (GET /v1/concepts/{id})
	GetConcept(ctx context.Context, request GetConceptRequestObject) (GetConceptResponseObject, error)
	// CreateContribution Propose a word (contributors)
	// (POST /v1/contributions)
	CreateContribution(ctx context.Context, request CreateContributionRequestObject) (CreateContributionResponseObject, error)
	// ListCredits The volunteers behind a language's data
	// (GET /v1/credits)
	ListCredits(ctx context.Context, request ListCreditsRequestObject) (ListCreditsResponseObject, error)
	// ListDisputes Disagreements waiting for a senior reviewer (senior reviewers)
	// (GET /v1/disputes)
	ListDisputes(ctx context.Context, request ListDisputesRequestObject) (ListDisputesResponseObject, error)
	// ResolveDispute Settle a dispute (senior reviewers)
	// (POST /v1/disputes/{sense_id}/resolution)
	ResolveDispute(ctx context.Context, request ResolveDisputeRequestObject) (ResolveDisputeResponseObject, error)
	// SearchEntries Search a language's dictionary entries
	// (GET /v1/entries/search)
	SearchEntries(ctx context.Context, request SearchEntriesRequestObject) (SearchEntriesResponseObject, error)
	// GetEntry A full dictionary entry
	// (GET /v1/entries/{id})
	GetEntry(ctx context.Context, request GetEntryRequestObject) (GetEntryResponseObject, error)
	// ListLanguages Supported and planned languages
	// (GET /v1/languages)
	ListLanguages(ctx context.Context, request ListLanguagesRequestObject) (ListLanguagesResponseObject, error)
	// Lookup Translate a word between English and Zambian languages
	// (GET /v1/lookup)
	Lookup(ctx context.Context, request LookupRequestObject) (LookupResponseObject, error)
	// GetMe The signed-in user, with role and review approvals
	// (GET /v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// SetCredit Choose whether to be credited by name
	// (PUT /v1/me/credit)
	SetCredit(ctx context.Context, request SetCreditRequestObject) (SetCreditResponseObject, error)
	// GetProviderQuality Acceptance and correction rates per AI provider and language (admin)
	// (GET /v1/provider-quality)
	GetProviderQuality(ctx context.Context, request GetProviderQualityRequestObject) (GetProviderQualityResponseObject, error)
	// GetNextReview The next concept to review (reviewers)
	// (GET /v1/review/next)
	GetNextReview(ctx context.Context, request GetNextReviewRequestObject) (GetNextReviewResponseObject, error)
	// ListReviewers Reviewers of a language with their agreement rates (senior reviewers)
	// (GET /v1/reviewers)
	ListReviewers(ctx context.Context, request ListReviewersRequestObject) (ListReviewersResponseObject, error)
	// MarkRetrained Record that a reviewer was retrained (senior reviewers)
	// (POST /v1/reviewers/{user_id}/retraining)
	MarkRetrained(ctx context.Context, request MarkRetrainedRequestObject) (MarkRetrainedResponseObject, error)
	// DeleteReviews Undo your own decision (reviewers)
	// (DELETE /v1/reviews)
	DeleteReviews(ctx context.Context, request DeleteReviewsRequestObject) (DeleteReviewsResponseObject, error)
	// CreateReviews Record review decisions (reviewers)
	// (POST /v1/reviews)
	CreateReviews(ctx context.Context, request CreateReviewsRequestObject) (CreateReviewsResponseObject, error)
	// ListSources The source register
	// (GET /v1/sources)
	ListSources(ctx context.Context, request ListSourcesRequestObject) (ListSourcesResponseObject, error)
	// CreateSource Add a source to the register (admin)
	// (POST /v1/sources)
	CreateSource(ctx context.Context, request CreateSourceRequestObject) (CreateSourceResponseObject, error)
	// DeleteSource Remove a source no item cites yet (admin)
	// (DELETE /v1/sources/{id})
	DeleteSource(ctx context.Context, request DeleteSourceRequestObject) (DeleteSourceResponseObject, error)
	// GetSource One source
	// (GET /v1/sources/{id})
	GetSource(ctx context.Context, request GetSourceRequestObject) (GetSourceResponseObject, error)
	// UpdateSource Replace a source's details (admin)
	// (PUT /v1/sources/{id})
	UpdateSource(ctx context.Context, request UpdateSourceRequestObject) (UpdateSourceResponseObject, error)
	// DownloadPermission Download the permission document (admin)
	// (GET /v1/sources/{id}/permission)
	DownloadPermission(ctx context.Context, request DownloadPermissionRequestObject) (DownloadPermissionResponseObject, error)
	// UploadPermission Upload the signed permission document (admin)
	// (PUT /v1/sources/{id}/permission)
	UploadPermission(ctx context.Context, request UploadPermissionRequestObject) (UploadPermissionResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

